class Solution {
public:
    int countSubMultisets(vector<int>& nums, int l, int r) {
        long long mod = 1e9 + 7;
        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        vector<long long> dp(r + 1, 0);
        dp[0] = 1;
        for (const auto& [x, c] : cnt) {
            if (x == 0) continue;
            vector<long long> next_dp(r + 1, 0);
            for (int rem = 0; rem < x; rem++) {
                long long window_sum = 0;
                for (int j = rem; j <= r; j += x) {
                    window_sum = (window_sum + dp[j]) % mod;
                    if (j - 1LL * (c + 1) * x >= 0) {
                        window_sum = (window_sum - dp[j - (c + 1) * x] + mod) % mod;
                    }
                    next_dp[j] = window_sum;
                }
            }
            dp = move(next_dp);
        }
        long long ans = 0;
        for (int i = l; i <= r; i++) ans = (ans + dp[i]) % mod;
        ans = (ans * (cnt[0] + 1)) % mod;
        return ans;
    }
};

class Solution {
    public int countSubMultisets(List<Integer> nums, int l, int r) {
        long mod = 1_000_000_007L;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.put(x, cnt.getOrDefault(x, 0) + 1);
        long[] dp = new long[r + 1];
        dp[0] = 1;
        for (Map.Entry<Integer, Integer> entry : cnt.entrySet()) {
            int x = entry.getKey(), c = entry.getValue();
            if (x == 0) continue;
            long[] nextDp = new long[r + 1];
            for (int rem = 0; rem < x; rem++) {
                long windowSum = 0;
                for (int j = rem; j <= r; j += x) {
                    windowSum = (windowSum + dp[j]) % mod;
                    if (j - (long) (c + 1) * x >= 0) {
                        windowSum = (windowSum - dp[j - (c + 1) * x] + mod) % mod;
                    }
                    nextDp[j] = windowSum;
                }
            }
            dp = nextDp;
        }
        long ans = 0;
        for (int i = l; i <= r; i++) ans = (ans + dp[i]) % mod;
        ans = (ans * (cnt.getOrDefault(0, 0) + 1)) % mod;
        return (int) ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} l
 * @param {number} r
 * @return {number}
 */
var countSubMultisets = function(nums, l, r) {
    const mod = 1000000007n;
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    let dp = new BigInt64Array(r + 1);
    dp[0] = 1n;
    for (const [x, c] of cnt.entries()) {
        if (x === 0) continue;
        const nextDp = new BigInt64Array(r + 1);
        const limit = (c + 1) * x;
        for (let rem = 0; rem < x; rem++) {
            let windowSum = 0n;
            for (let j = rem; j <= r; j += x) {
                windowSum = (windowSum + dp[j]) % mod;
                if (j >= limit) {
                    windowSum = (windowSum - dp[j - limit] + mod) % mod;
                }
                nextDp[j] = windowSum;
            }
        }
        dp = nextDp;
    }
    let ans = 0n;
    for (let i = l; i <= r; i++) ans = (ans + dp[i]) % mod;
    const zeros = BigInt(cnt.get(0) || 0);
    ans = (ans * (zeros + 1n)) % mod;
    return Number(ans);
};
